"""Dependency-free Chrome headless checks. Run: python tests/check_browser.py"""
from pathlib import Path
import os
import subprocess
import tempfile
import html
import re

ROOT = Path(__file__).resolve().parents[1]
chrome = next((Path(p) for p in [
    os.environ.get('CHROME_PATH', ''),
    'C:/Program Files/Google/Chrome/Application/chrome.exe',
    'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',
] if p and Path(p).is_file()), None)
if not chrome:
    raise SystemExit('Set CHROME_PATH to a Chrome or Edge executable.')
test_js = r'''
const results=[];
function check(name,fn){try{fn();results.push('PASS '+name)}catch(e){results.push('FAIL '+name+': '+e.message)}}
function assert(v,msg='assertion failed'){if(!v)throw Error(msg)}
function fresh(){mode='solo';myIndex=0;race=newRace(1,'normal',12345);race.t=0;race.nextBus=999;race.nextCar=999;paused=false;}
check('exact route and previous-stop boundaries',()=>{
 assert(STOPS.map(s=>s.d).join(',')==='0,50,650,900,1200,1500');
 for(const [d,want] of [[30,0],[50,0],[51,50],[650,50],[651,650],[900,650],[901,900],[1201,1200]])assert(previousStop(d).d===want,'stop at '+d);
});
check('automatic movement and jumping',()=>{fresh();step(.5);assert(race.players[0].d===6);action(race.players[0],'jump');step(.1);assert(race.players[0].jump>0)});
check('keyboard works immediately after start click',()=>{$('soloBtn').focus();$('soloBtn').click();race.t=0;document.body.dispatchEvent(new KeyboardEvent('keydown',{code:'Space',bubbles:true}));assert(race.players[0].jump>0)});
check('rock collision versus jump clearance',()=>{fresh();let p=race.players[0];p.d=94.9;step(STEP);assert(p.stun===1);fresh();p=race.players[0];p.d=94.9;p.jump=5;step(STEP);assert(p.stun===0)});
check('bus takes player to nearest earlier stop and clears hazards',()=>{fresh();let p=race.players[0];const future=race.rocks.findIndex(r=>r.d>700);p.d=700;p.hits=[1,future];race.buses=[{id:0,d:700+BUS_FRONT}];step(STEP);assert(p.ride===650);for(let i=0;i<60;i++)step(STEP);assert(p.ride===null&&p.d>=650&&p.d<660);assert(!p.hits.includes(future));assert(p.inv.bus>0&&p.inv.car===0&&p.inv.rock===0)});
check('right-arrow avoids bus without cooldown, jump does not',()=>{fresh();let p=race.players[0];p.d=700;race.buses=[{id:0,d:700+BUS_FRONT}];action(p,'dodge');step(STEP);assert(p.ride===null);action(p,'dodge');assert(p.dodge===.7);fresh();p=race.players[0];p.d=700;p.jump=10;race.buses=[{id:0,d:700+BUS_FRONT}];step(STEP);assert(p.ride===650)});
check('bus dodge expires after 0.7 seconds',()=>{fresh();const p=race.players[0];p.d=700;race.buses=[{id:8,d:700+BUS_FRONT}];action(p,'dodge');step(STEP);assert(p.ride===null);for(let i=0;i<41;i++)step(STEP);assert(p.dodge===0&&!p.avoidedBuses.length);race.buses=[{id:9,d:p.d+BUS_FRONT}];step(STEP);assert(p.ride!==null)});
check('avoidance belongs to each player',()=>{race=newRace(2);race.t=0;race.nextBus=999;race.players.forEach(p=>p.d=700);race.buses=[{id:1,d:700+BUS_FRONT}];action(race.players[0],'dodge');step(STEP);assert(race.players[0].ride===null&&race.players[1].ride===650)});
check('two bus routes repeat in sequence',()=>{fresh();const routes=[];for(let i=0;i<3;i++){race.buses=[];race.nextBus=race.t;step(STEP);routes.push(race.buses.at(-1).route)}assert(routes.join(',')==='5513,5516,5513')});
check('car dodge lasts 0.7 seconds and right arrow does not avoid cars',()=>{fresh();const p=race.players[0];p.d=700;race.cars=[{id:1,d:700+CAR_FRONT}];action(p,'carDodge');step(STEP);assert(p.knockback===null);race.cars=[];for(let i=0;i<41;i++)step(STEP);assert(p.carDodge===0&&!p.avoidedCars.length);race.cars=[{id:2,d:p.d+CAR_FRONT}];action(p,'dodge');step(STEP);assert(p.knockback!==null)});
check('jump cannot avoid car and left arrow cannot avoid bus',()=>{fresh();let p=race.players[0];p.d=700;p.jump=9;race.cars=[{id:1,d:700+CAR_FRONT,color:CAR_COLORS[0],model:'suv'}];step(STEP);assert(p.knockback!==null);fresh();p=race.players[0];p.d=700;race.buses=[{id:1,d:700+BUS_FRONT}];action(p,'carDodge');step(STEP);assert(p.ride===650)});
check('car launches an arc and lands exactly 30 meters back',()=>{fresh();const p=race.players[0];p.d=700;race.cars=[{id:1,d:700+CAR_FRONT,color:CAR_COLORS[0],model:'sedan'}];step(STEP);const from=p.d;step(FLIGHT_TIME/2);assert(Math.abs(p.d-(from-15))<.001&&p.jump>35);const height=p.jump;action(p,'jump');action(p,'carDodge');assert(p.jump===height&&p.carDodge===0);race.buses=[{id:1,d:p.d+BUS_FRONT}];step(STEP);assert(p.ride===null);step(FLIGHT_TIME);assert(p.knockback===null&&p.jump===0&&Math.abs(p.d-(from-30))<.001&&p.inv.car===1&&p.inv.bus===0);step(STEP);assert(p.d>from-30)});
check('car flight clamps at start and time keeps running',()=>{fresh();const p=race.players[0];p.d=10;race.cars=[{id:1,d:10+CAR_FRONT,color:CAR_COLORS[0],model:'suv'}];step(STEP);step(FLIGHT_TIME);assert(p.d===0&&p.knockback===null&&race.t>1);fresh();race.t=180.9;race.players[0].knockback={from:700,to:670,elapsed:0,startJump:0};step(.2);assert(race.done&&race.winner===null)});
check('switching avoidance immediately cancels opposite vehicle protection',()=>{for(const first of ['dodge','carDodge']){fresh();const p=race.players[0];p.d=700;const isBus=first==='dodge';race[isBus?'buses':'cars']=[{id:1,d:700+(isBus?BUS_FRONT:CAR_FRONT)}];action(p,first);step(STEP);assert(p.ride===null&&p.knockback===null);action(p,isBus?'carDodge':'dodge');assert(p[isBus?'dodge':'carDodge']===0);race[isBus?'buses':'cars'][0].d=p.d+(isBus?BUS_FRONT:CAR_FRONT);step(STEP);assert(isBus?p.ride!==null:p.knockback!==null)}});
check('all eight car model and color combinations spawn',()=>{fresh();const combos=new Set();for(let i=0;i<8;i++){race.cars=[];assert(spawnTraffic('car'));const c=race.cars[0];combos.add(c.model+c.color)}assert(combos.size===8)});
check('traffic spacing survives two racers, stops and bus returns',()=>{race=newRace(2);race.t=0;race.players[1].d=120;let sawBus=false,sawCar=false;for(let i=0;i<10000&&!race.done;i++){step(STEP);sawBus ||= race.buses.length>0;sawCar ||= race.cars.length>0;const traffic=[...race.buses,...race.cars];for(let a=0;a<traffic.length;a++)for(let b=a+1;b<traffic.length;b++)assert(Math.abs(traffic[a].d-traffic[b].d)>=trafficGap()-.001,'unsafe traffic spacing')}assert(sawBus&&sawCar);assert(Math.abs((trafficGap()-BUS_CONTACT-CAR_CONTACT)/(SPEED+CAR_SPEED)-DIFFICULTIES[race.difficulty].reaction)<.001)});
check('camera shows exactly 30 meters in each direction',()=>{fresh();race.players[0].d=700;render(0);assert(Math.abs(sx(670))<.001);assert(Math.abs(sx(700)-W/2)<.001);assert(Math.abs(sx(730)-W)<.001)});
check('random courses vary but preserve jump safety on all difficulties',()=>{for(const difficulty of Object.keys(DIFFICULTIES)){let early=0,late=0;for(let seed=1;seed<=20;seed++){const items=makeRocks(difficulty,seed);for(let i=1;i<items.length;i++)assert((items[i].d-items[i-1].d)/SPEED>=2*JUMP_SPEED/GRAVITY+DIFFICULTIES[difficulty].recovery);early+=items.filter(r=>r.d<500).length;late+=items.filter(r=>r.d>=1000).length}assert(late>early);assert(JSON.stringify(makeRocks(difficulty,1))!==JSON.stringify(makeRocks(difficulty,2)))}assert(JSON.stringify(makeRocks('normal',123))===JSON.stringify(makeRocks('normal',123)))});
check('all difficulty courses are jumpable without collisions',()=>{for(const difficulty of Object.keys(DIFFICULTIES))for(const seed of [1,19,101]){fresh();race=newRace(1,difficulty,seed);race.t=0;race.nextBus=race.nextCar=999;const p=race.players[0];for(let i=0;i<9000&&!race.done;i++){const next=race.rocks.find(r=>r.d>p.d);if(next&&next.d-p.d<=4&&p.jump===0)action(p,'jump');step(STEP);assert(p.stun===0,'unavoidable obstacle at '+p.d+' '+difficulty)}assert(race.done&&race.winner===0)}});
check('random traffic is denser and cars outnumber buses',()=>{for(const difficulty of Object.keys(DIFFICULTIES)){race=newRace(1,difficulty,12345);race.t=0;race.players[0].inv={rock:999,car:999,bus:999};for(let i=0;i<7200&&!race.done;i++)step(STEP);assert(race.busId>=8,'buses postponed');assert(race.carId>=race.busId*2,'not enough cars');const samples=new Set(Array.from({length:10},()=>carInterval().toFixed(3)));assert(samples.size>5)}});
check('result menu uses minutes and seconds and routes back to main',()=>{selectDifficulty('hard');mode='solo';start(1);race.players[0].finish=159.73;race.winner=0;race.done=true;endScreen();assert($('panelTitle').textContent==='무사히 도착했다!'&&$('panelText').textContent==='02:39.73','finish title or clock: '+$('panelTitle').textContent+' '+$('panelText').textContent);assert($('onlineBtn').hidden&&!$('mainBtn').hidden&&$('difficultyPicker').hidden&&$('helpBtn').hidden,'result buttons');$('mainBtn').click();assert(mode==='menu'&&!$('difficultyPicker').hidden&&!$('onlineBtn').hidden&&$('mainBtn').hidden,'main buttons');$('soloBtn').click();assert(race.difficulty==='hard','replay difficulty '+race.difficulty);race.done=true;race.winner=null;endScreen();assert($('panelTitle').textContent==='수업에 지각했다!'&&$('panelText').hidden&&$('panelFlag').hidden,'game over panel '+$('panelTitle').textContent);selectDifficulty('normal');menu()});
check('finish and time limit',()=>{fresh();race.players[0].d=1499.9;step(STEP);assert(race.done&&race.winner===0);fresh();race.t=180.99;step(STEP);assert(race.done&&race.winner===null&&race.t===181)});
check('online second-player victory and independent camera',()=>{race=newRace(2);race.t=0;race.nextBus=999;race.players[1].d=1499.9;step(STEP);assert(race.winner===1);myIndex=0;render(1);let firstCam=cam;myIndex=1;render(1);assert(cam-firstCam>4000);assert(validState(race))});
check('minimal room menu and numeric entry',()=>{$('onlineBtn').click();assert(!$('roomChoices').hidden&&$('waitingRoom').hidden&&$('joinRoom').hidden&&$('networkStatus').textContent==='');$('joinBtn').click();assert(!$('joinRoom').hidden&&$('roomChoices').hidden);$('remoteCode').value='ab12 345678';$('remoteCode').dispatchEvent(new Event('input'));assert($('remoteCode').value==='123456');$('closeOnline').click();assert(!$('onlineDialog').open&&peer===null)});
check('crash sound fires once and bus bell precedes arrival once',()=>{fresh();const p=race.players[0];p.d=700;race.cars=[{id:2,d:700+CAR_FRONT,color:CAR_COLORS[1],model:'suv'}];step(STEP);assert(p.carHits===1);step(.1);assert(p.carHits===1);fresh();const q=race.players[0];q.d=840;race.buses=[{id:4,d:840+BUS_FRONT,route:'5513'}];step(STEP);assert(q.ride===650&&q.busBells===0);let heard=false;for(let i=0;i<150;i++){step(STEP);if(q.busBells===1&&q.ride!==null)heard=true;if(q.ride===null)break}assert(heard&&q.busBells===1&&q.ride===null)});
check('vehicle sound dispatch is local, deduplicated and pauses with solo',()=>{fresh();vehicleAudioSeen={hits:0,bells:0};const saved={playSfx,playBusBell,startBusEngine,stopBusEngine};let hits=0,bells=0,engines=0,stops=0;try{playSfx=k=>{if(k==='crash')hits++;return true};playBusBell=()=>{bells++;return true};startBusEngine=()=>engines++;stopBusEngine=()=>stops++;race.players[0].carHits=1;syncVehicleAudio();syncVehicleAudio();assert(hits===1);race.players[0].ride=50;race.players[0].busBells=1;syncVehicleAudio();syncVehicleAudio();assert(bells===1&&engines===2);paused=true;syncVehicleAudio();assert(engines===2&&stops>0)}finally{Object.assign(window,saved);playSfx=saved.playSfx;playBusBell=saved.playBusBell;startBusEngine=saved.startBusEngine;stopBusEngine=saved.stopBusEngine;paused=false}});
check('countdown beeps once per number and once at go, respecting pause and exit',()=>{mode='solo';myIndex=0;start(1);const original=playSfx,calls=[];try{playSfx=key=>{calls.push(key);return true};for(const time of [-3,-3,-2,-2,-1,-1,0,0]){race.t=time;updateHud()}assert(calls.join(',')==='countdown,countdown,countdown,go');start(1);paused=true;updateHud();assert(calls.length===4);paused=false;updateHud();assert(calls.length===5);menu();updateHud();assert(calls.length===5)}finally{playSfx=original}});
check('BGM waits for countdown and sound effects require accepted actions',()=>{mode='solo';myIndex=0;start(1);assert(!bgmWanted);step(1);assert(!bgmWanted);step(1);assert(!bgmWanted);step(1);assert(bgmWanted);const original=playSfx,calls=[];try{playSfx=k=>calls.push(k);input('jump');input('jump');input('dodge');input('carDodge');assert(calls.join(',')==='jump,dodge,carDodge');race.players[0].stun=1;input('jump');assert(calls.length===3)}finally{playSfx=original}menu();assert(!bgmWanted&&bgm.paused)});
check('expert reaction gap is 0.25 seconds and selectable',()=>{selectDifficulty('expert');mode='solo';start(1);assert(race.difficulty==='expert');assert(Math.abs((trafficGap()-BUS_CONTACT-CAR_CONTACT)/(SPEED+BUS_SPEED)-.25)<.001);selectDifficulty('normal');menu()});
check('route markers align with stops and update for local identity and retreat',()=>{fresh();STOPS.forEach((s,i)=>assert(Math.abs(routePosition(s.d)-i*20)<.001));assert(routePosition(-30)===0&&routePosition(1600)===100);updateHud();assert($('routeRival').hidden);race=newRace(2);race.players[0].d=650;race.players[1].d=900;myIndex=1;updateHud();assert(parseFloat($('routeMe').style.left)===60&&parseFloat($('routeRival').style.left)===40&&!$('routeRival').hidden);race.players[1].d=650;updateHud();assert($('routeMe').style.top!==$('routeRival').style.top);race.players[1].d=620;updateHud();assert(parseFloat($('routeMe').style.left)<40);myIndex=0});
check('car avoidance drawing ends with its timer',()=>{fresh();const p=race.players[0];action(p,'carDodge');assert(behindCars(p));for(let i=0;i<42;i++)step(STEP);assert(!behindCars(p))});
check('overlapping players keep local runner in front while avoiding cars',()=>{race=newRace(2);race.t=0;mode='solo';myIndex=0;race.players.forEach(p=>p.d=700);race.cars=[{id:1,d:700+CAR_FRONT,color:CAR_COLORS[0],model:'sedan'}];action(race.players[0],'carDodge');const saved={human,car};const calls=[];try{human=(x,y,color)=>calls.push(color);car=()=>calls.push('car');render(0);assert(calls.indexOf('#dd6459')<calls.indexOf('#347cdb')&&calls.indexOf('#347cdb')<calls.indexOf('car'))}finally{human=saved.human;car=saved.car}});
check('minimal menu and large countdown show 3 2 1 then disappear',()=>{menu();assert($('panelTitle').textContent==='윗공대 오르기'&&$('panelFlag').hidden&&$('panelText').hidden);mode='solo';start(1);for(const [time,want] of [[-3,'3'],[-2,'2'],[-1,'1']]){race.t=time;updateHud();assert(!$('countdown').hidden&&$('countdown').textContent===want)}race.t=0;updateHud();assert($('countdown').hidden)});
check('settings hide control hints but preserve collision notices',()=>{fresh();race.players[0].d=700;race.cars=[{id:3,d:720,color:CAR_COLORS[0],model:'sedan'}];$('settingsBtn').click();assert(paused&&$('settingsDialog').open);$('hintsToggle').checked=false;$('hintsToggle').dispatchEvent(new Event('change'));$('settingsDialog').close();paused=false;updateHud();assert($('status').textContent==='');race.players[0].knockback={from:700,to:670,elapsed:.2,startJump:0};updateHud();assert($('status').textContent!=='');race.players[0].knockback=null;$('hintsToggle').checked=true;$('hintsToggle').dispatchEvent(new Event('change'));updateHud();assert($('status').textContent.includes('←'))});
check('ground stun permits both vehicle dodges but blocks jumping',()=>{for(const key of ['dodge','carDodge']){fresh();const p=race.players[0];p.d=700;p.stun=1;p.stunKind='rock';assert(!action(p,'jump'));assert(action(p,key));race[key==='dodge'?'buses':'cars']=[{id:1,d:700+(key==='dodge'?BUS_FRONT:CAR_FRONT)}];step(STEP);assert(p.ride===null&&p.knockback===null&&p.stun>0)}});
check('each immunity only protects its own obstacle kind',()=>{for(const immune of ['rock','car','bus']){for(const hazard of ['rock','car','bus']){fresh();const p=race.players[0];p.d=700;p.inv[immune]=2;if(hazard==='rock')race.rocks=[{d:700.1,type:0}];else race[hazard==='bus'?'buses':'cars']=[{id:1,d:700+(hazard==='bus'?BUS_FRONT:CAR_FRONT)}];step(STEP);const hit=hazard==='rock'?p.stun>0:hazard==='bus'?p.ride!==null:p.knockback!==null;assert(hit===(immune!==hazard),immune+' immunity versus '+hazard)}}});
check('jump does not cancel vehicle dodge',()=>{fresh();const p=race.players[0];action(p,'dodge');action(p,'jump');assert(p.dodge===.7&&p.jump>0)});
check('vehicle bodies and rear ends never collide after the nose passed',()=>{for(const kind of ['bus','car'])for(const offset of [0,-2]){fresh();const p=race.players[0];p.d=700;race[kind==='bus'?'buses':'cars']=[{id:1,d:700+offset}];step(STEP);assert(p.ride===null&&p.knockback===null,kind+' body collision')}});
check('front sweep catches fast crossings without body-wide collision',()=>{for(const kind of ['bus','car']){fresh();const p=race.players[0];p.d=700;const front=kind==='bus'?BUS_FRONT:CAR_FRONT;race[kind==='bus'?'buses':'cars']=[{id:1,d:700+front+2}];step(.2);assert(kind==='bus'?p.ride!==null:p.knockback!==null,kind+' missed crossing')}});
check('dodge may end or switch after nose passes without body collision',()=>{for(const kind of ['bus','car']){fresh();const p=race.players[0];p.d=700;const front=kind==='bus'?BUS_FRONT:CAR_FRONT;race[kind==='bus'?'buses':'cars']=[{id:1,d:700+front}];action(p,kind==='bus'?'dodge':'carDodge');for(let i=0;i<3;i++)step(STEP);action(p,kind==='bus'?'carDodge':'dodge');step(STEP);assert(p.ride===null&&p.knockback===null,kind+' collided after passing nose')}});
fresh();mode='menu';menu();render(0);updateHud();
const out=document.createElement('pre');out.id='qa-results';out.textContent=results.join('\n');document.body.append(out);
'''
qa = ROOT / '.qa'
qa.mkdir(exist_ok=True)
source = (ROOT / 'index.html').read_text(encoding='utf-8')
source = source.replace('<head>', '<head><base href="../">', 1)
source = source.replace('<script>', '<script>window.requestAnimationFrame=()=>0;</script><script>', 1)
source = source.replace('</script></body>', test_js + '</script></body>')
scene = os.environ.get('QA_SCENE')
if scene is not None:
    distance = float(scene)
    source = source.replace('fresh();mode=\'menu\';menu();render(0);updateHud();',
        f"fresh();race.players[0].d={distance};$('overlay').hidden=true;render(0);updateHud();")
testfile = qa / 'checks.html'
testfile.write_text(source, encoding='utf-8')
with tempfile.TemporaryDirectory(prefix='uphill-browser-') as profile:
    result = subprocess.run([str(chrome), '--headless', '--disable-gpu', '--no-first-run',
        '--no-default-browser-check', '--allow-file-access-from-files',
        '--user-data-dir=' + profile, '--dump-dom', '--timeout=10000',
        '--screenshot=' + str(qa / (('scene-' + scene + '.png') if scene else 'preview.png')), '--window-size=' + os.environ.get('QA_VIEWPORT', '1440,1100'),
        testfile.as_uri()], capture_output=True, encoding='utf-8', errors='replace', timeout=35)
    match = re.search(r'<pre id="qa-results">(.*?)</pre>', result.stdout, re.S)
    if not match:
        print(result.stderr[-2500:])
        raise SystemExit('Browser did not produce test results.')
    report = html.unescape(match.group(1))
    print(report)
    if 'FAIL' in report:
        raise SystemExit(1)
print('Screenshot: .qa/' + (('scene-' + scene + '.png') if scene else 'preview.png'))
